<x-restaurant-layout title="Calendrier d’ouverture" :admin="true"><div class="section-heading"><div><p class="eyebrow">LE RYTHME DU RESTAURANT</p><h1>Calendrier d’ouverture</h1></div><a href="{{ route('admin.slots') }}">Consulter les créneaux ↗</a></div><div class="notice">Les exceptions remplacent les horaires habituels. La fermeture d’une journée ne supprime aucune commande.</div>@include('restaurant.admin.month')<section class="panel"><h2>Horaires habituels</h2>@foreach($weekly as $day)<form class="hours-row" method="post" action="{{ route('admin.hours') }}">@csrf<input type="hidden" name="weekday" value="{{ $day->weekday }}"><strong>{{ [1 => 'Lundi', 'Mardi', 'Mercredi', 'Jeudi', 'Vendredi', 'Samedi', 'Dimanche'][$day->weekday] }}</strong><label><span class="sr-only">Ouverture</span><select name="is_open"><option value="1" @selected($day->is_open)>Ouvert</option><option value="0" @selected(!$day->is_open)>Fermé</option></select></label><label>De<input name="starts_at" type="time" value="{{ substr($day->starts_at, 0, 5) }}" required></label><label>À<input name="ends_at" type="time" value="{{ substr($day->ends_at, 0, 5) }}" required></label><button class="button small secondary">Enregistrer</button></form>@endforeach</section><div class="checkout-grid mt-6"><form class="panel" method="post" action="{{ route('admin.exceptions') }}">@csrf<h2>Ouverture ou fermeture exceptionnelle</h2><label>Date<input type="date" name="date" value="{{ old('date') }}" required></label><label>État<select name="is_open"><option value="0">Fermé</option><option value="1">Ouvert exceptionnellement</option></select></label><div class="two-fields"><label>Début<input type="time" name="starts_at" value="{{ old('starts_at', '18:00') }}" required></label><label>Fin<input type="time" name="ends_at" value="{{ old('ends_at', '23:00') }}" required></label></div><label>Motif<input name="reason" maxlength="255" value="{{ old('reason') }}" placeholder="Vacances, événement…"></label><button class="button">Enregistrer l’exception</button><p class="muted">Saisir une date déjà présente remplace son exception.</p></form><section class="panel"><h2>Exceptions enregistrées</h2>@forelse($exceptions as $exception)<div class="exception-row"><div><a href="{{ route('admin.slots', ['date' => $exception->date]) }}"><strong>{{ \Carbon\CarbonImmutable::parse($exception->date)->format('d/m/Y') }}</strong></a><p>{{ $exception->is_open ? substr($exception->starts_at, 0, 5).' – '.substr($exception->ends_at, 0, 5) : 'Fermé' }} · {{ $exception->reason }}</p></div><form method="post" action="{{ route('admin.exceptions.delete', $exception->id) }}">@csrf @method('DELETE')<button class="text-button">Rétablir les horaires habituels</button></form></div>@empty<p>Aucune exception enregistrée.</p>@endforelse</section></div></x-restaurant-layout>
